function smallestRangeI(nums, k) {
  let low = nums[0];
  let high = nums[0];

  for (const value of nums) {
    low = Math.min(low, value);
    high = Math.max(high, value);
  }

  const gap = high - low - 2 * k;
  return Math.max(0, gap);
}

