function smallestRangeI(nums, k) {
  // Try each candidate lower end of the final window (some value moved fully up or down)
  // and measure how wide the window must be for every value to reach it.
  let best = Infinity;
  for (const c of nums) {
    for (const start of [c - k, c + k]) {
      let width = 0;
      let ok = true;
      for (const v of nums) {
        if (v + k < start) { ok = false; break; }
        const lowest = Math.max(start, v - k);
        width = Math.max(width, lowest - start);
      }
      if (ok) best = Math.min(best, width);
    }
  }
  return best;
}

